package br.com.eventflow.controller; import br.com.eventflow.model.*; import br.com.eventflow.repository.*; import org.springframework.web.bind.annotation.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import java.util.*; @RestController @RequestMapping("/api") @CrossOrigin(origins={"http://localhost:5173","http://127.0.0.1:5173"}) public class ApiController { private final UsuarioRepository u; private final EventoRepository e; private final CategoriaRepository c; private final LocalEventoRepository l; private final LoteIngressoRepository li; private final PedidoRepository p; private final IngressoRepository i; private final BCryptPasswordEncoder enc; public ApiController(UsuarioRepository u,EventoRepository e,CategoriaRepository c,LocalEventoRepository l,LoteIngressoRepository li,PedidoRepository p,IngressoRepository i,BCryptPasswordEncoder enc){this.u=u;this.e=e;this.c=c;this.l=l;this.li=li;this.p=p;this.i=i;this.enc=enc;} record Auth(String nome,String email,String senha,TipoUsuario tipoUsuario){} record EventoReq(String nome,String descricao,String dataHora,Integer capacidade,Long organizadorId,Long categoriaId,Long localId,String status){} record LoteReq(String nome,java.math.BigDecimal preco,Integer quantidadeTotal,Long eventoId){} record CompraReq(Long participanteId,Long loteId,Integer quantidade){} @PostMapping("/auth/cadastro") public Usuario cadastro(@RequestBody Auth r){if(u.findByEmail(r.email()).isPresent())throw new RuntimeException("E-mail já cadastrado"); Usuario x=new Usuario();x.nome=r.nome();x.email=r.email();x.senhaHash=enc.encode(r.senha());x.tipoUsuario=r.tipoUsuario()==null?TipoUsuario.PARTICIPANTE:r.tipoUsuario();return u.save(x);} @PostMapping("/auth/login") public Usuario login(@RequestBody Auth r){Usuario x=u.findByEmail(r.email()).orElseThrow(); if(!enc.matches(r.senha(),x.senhaHash))throw new RuntimeException("Login inválido"); return x;} @GetMapping("/eventos") public List<Evento> eventos(){return e.findByStatus(StatusEvento.PUBLICADO);} @GetMapping("/eventos/{id}") public Evento evento(@PathVariable Long id){return e.findById(id).orElseThrow();} @GetMapping("/eventos/{id}/lotes") public List<LoteIngresso> lotes(@PathVariable Long id){return li.findByEventoId(id);} @GetMapping("/categorias") public List<Categoria> categorias(){return c.findAll();} @GetMapping("/locais") public List<LocalEvento> locais(){return l.findAll();} @GetMapping("/organizador/{id}/eventos") public List<Evento> orgEventos(@PathVariable Long id){return e.findByOrganizadorId(id);} @GetMapping("/organizador/{id}/vendas") public List<Pedido> vendas(@PathVariable Long id){return p.findByLoteIngressoEventoOrganizadorIdOrderByDataDesc(id);} @GetMapping("/usuarios/{id}/historico") public List<Pedido> hist(@PathVariable Long id){return p.findByParticipanteIdOrderByDataDesc(id);} @GetMapping("/usuarios/{id}/ingressos") public List<Ingresso> ingressos(@PathVariable Long id){return i.findByPedidoParticipanteId(id);} @PostMapping("/eventos") public Evento novoEvento(@RequestBody EventoReq r){Evento x=new Evento();x.nome=r.nome();x.descricao=r.descricao();x.dataHora=java.time.LocalDateTime.parse(r.dataHora());x.capacidade=r.capacidade();x.status=StatusEvento.valueOf(r.status()==null?"RASCUNHO":r.status());x.organizador=u.findById(r.organizadorId()).orElseThrow();x.categoria=c.findById(r.categoriaId()).orElseThrow();x.localEvento=l.findById(r.localId()).orElseThrow();return e.save(x);} @PostMapping("/lotes") public LoteIngresso novoLote(@RequestBody LoteReq r){Evento ev=e.findById(r.eventoId()).orElseThrow(); if(r.quantidadeTotal()>ev.capacidade)throw new RuntimeException("Quantidade excede capacidade"); LoteIngresso x=new LoteIngresso();x.nome=r.nome();x.preco=r.preco();x.quantidadeTotal=r.quantidadeTotal();x.quantidadeDisponivel=r.quantidadeTotal();x.evento=ev;return li.save(x);} @PostMapping("/pedidos/comprar") public Map<String,Object> comprar(@RequestBody CompraReq r){Usuario part=u.findById(r.participanteId()).orElseThrow();LoteIngresso lote=li.findById(r.loteId()).orElseThrow();if(r.quantidade()==null||r.quantidade()<1)throw new RuntimeException("Quantidade inválida");if(!Boolean.TRUE.equals(lote.ativo)||r.quantidade()>lote.quantidadeDisponivel)throw new RuntimeException("Quantidade indisponível"); lote.quantidadeDisponivel-=r.quantidade();if(lote.quantidadeDisponivel==0)lote.ativo=false;li.save(lote);Pedido ped=new Pedido();ped.participante=part;ped.loteIngresso=lote;ped.quantidade=r.quantidade();ped.valorTotal=lote.preco.multiply(java.math.BigDecimal.valueOf(r.quantidade()));ped.status="CONFIRMADO";p.save(ped);List<Ingresso> emitidos=new ArrayList<>();for(int n=0;n<r.quantidade();n++){Ingresso ing=new Ingresso();ing.pedido=ped;ing.evento=lote.evento;emitidos.add(i.save(ing));} return Map.of("pedido",ped,"ingressos",emitidos,"quantidadeDisponivel",lote.quantidadeDisponivel);} }